import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Quaternion } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};
  const cleanupFns = [];

  // ========== STAGE BACKDROP ==========
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // ========== QUOTE PANEL PLANE ==========
  const planeGeom = new PlaneGeometry(3, 2);
  const planeMat = new MeshBasicNodeMaterial({
    color: 0xe8ecf2,
  });

  // Load the feature card image and apply as texture
  const imagePromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    planeMat.map = tex;
    planeMat.needsUpdate = true;
  });

  const plane = new Mesh(planeGeom, planeMat);
  plane.position.copy(new Vector3(1.25, 1.6, 0));
  plane.renderOrder = 10;
  group.add(plane);

  // ========== PARALLAX SCROLL PRIMITIVE ==========
  let primitiveResult = null;
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    const parallaxCfg = config.cinematicPrimitives.find((p) => p.name === 'parallax-scroll');
    if (parallaxCfg) {
      primitiveResult = ctx.primitives['parallax-scroll'](plane, parallaxCfg.params || { intensity: 0.25 });
      if (primitiveResult && primitiveResult.cleanup) {
        cleanupFns.push(() => primitiveResult.cleanup());
      }
    }
  }

  // ========== INTERACTION: HOVER (rise-in) ==========
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    plane.position,
    {
      y: plane.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  group.userData.handlers.pointerEnter = () => {
    hoverTimeline.play();
  };

  group.userData.handlers.pointerLeave = () => {
    hoverTimeline.reverse();
  };

  // ========== INTERACTION: CLICK (press-down + emit) ==========
  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(
    plane.scale,
    {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
    },
    0
  );

  group.userData.handlers.click = () => {
    pressTimeline.restart();
    // Emit navigation event for pricing selection
    ctx.emit('hub-pricing.select', { source: 'quote-panel' });
  };

  // ========== CLEANUP ==========
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    pressTimeline.kill();
    cleanupFns.forEach((fn) => fn());
    planeMat.dispose();
    planeGeom.dispose();
    backdropMat.dispose();
    backdropGeom.dispose();
  };

  return group;
}
